<?php
require_once 'functions.php';require_login();$u=current_user();$sql="SELECT c.case_id,s.student_number,CONCAT(s.first_name,' ',s.last_name) student_name,v.violation_name,c.incident_date,c.sanction,c.remarks,c.status FROM cases c JOIN students s ON s.student_id=c.student_id JOIN violations v ON v.violation_id=c.violation_id";
if($u['role']==='Student'){$q=$pdo->prepare($sql.' WHERE c.student_id=? ORDER BY c.incident_date DESC');$q->execute([$u['student_id']]);$rows=$q->fetchAll();}else{$rows=$pdo->query($sql.' ORDER BY c.incident_date DESC')->fetchAll();}page_header('Disciplinary Records');?>
<h1><?=$u['role']==='Admin'?'Disciplinary Records':'My Disciplinary Records'?></h1><p class="muted"><?=$u['role']==='Admin'?'View and manage student disciplinary records.':'Only records linked to your student account are displayed.'?></p><?php if(isset($_GET['saved'])):?><div class="alert">Case record saved successfully.</div><?php endif;?>
<section class="panel"><?php if($u['role']==='Admin'):?><p><a class="btn primary" href="case_form.php">+ Add Disciplinary Case</a> <a class="btn" href="backup.php">Database Backup</a></p><?php endif;?><div class="table-wrap"><table><thead><tr><?php if($u['role']==='Admin'):?><th>Student No.</th><th>Student Name</th><?php endif;?><th>Date</th><th>Violation</th><th>Sanction</th><th>Status</th><th>Remarks</th><?php if($u['role']==='Admin'):?><th>Actions</th><?php endif;?></tr></thead><tbody>
<?php foreach($rows as $r):?><tr><?php if($u['role']==='Admin'):?><td><?=e($r['student_number'])?></td><td><?=e($r['student_name'])?></td><?php endif;?><td><?=e($r['incident_date'])?></td><td><?=e($r['violation_name'])?></td><td><?=e($r['sanction'])?></td><td><span class="status"><?=e($r['status'])?></span></td><td><?=e($r['remarks'])?></td><?php if($u['role']==='Admin'):?><td><a class="btn" href="case_form.php?id=<?=(int)$r['case_id']?>">Edit</a> <a class="btn" href="notice.php?id=<?=(int)$r['case_id']?>">Notice</a></td><?php endif;?></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="9">No records found.</td></tr><?php endif;?></tbody></table></div></section><?php page_footer();?>